<?php
namespace Kitgenix\MultiStore\Admin;

use Kitgenix\MultiStore\Repository\MappingRepository;
use Kitgenix\MultiStore\Repository\StoreRepository;
use Kitgenix\MultiStore\Support\Settings;
use Kitgenix\MultiStore\Sync\ProductSync;

final class ProductPanel {
    public function __construct(private StoreRepository$stores,private MappingRepository$mappings,private ProductSync$sync,private Settings$settings){}
    public function hooks():void{add_filter('woocommerce_product_data_tabs',array($this,'tab'));add_action('woocommerce_product_data_panels',array($this,'panel'));add_action('woocommerce_process_product_meta',array($this,'save'),30);}
    public function tab(array$tabs):array{$tabs['kitgenix_multistore_sync_for_woocommerce_multistore']=array('label'=>__('MultiStore','kitgenix-multistore'),'target'=>'kitgenix_multistore_sync_for_woocommerce_product_data','class'=>array('show_if_simple','show_if_variable','show_if_external','show_if_grouped'),'priority'=>85);return$tabs;}
    public function panel():void{global$post;if(!$post)return;$network=(string)get_post_meta($post->ID,'_kitgenix_multistore_sync_for_woocommerce_network_id',true);$enabled=get_post_meta($post->ID,'_kitgenix_multistore_sync_for_woocommerce_sync_enabled',true);if(''===$enabled)$enabled='yes';$targets=(array)get_post_meta($post->ID,'_kitgenix_multistore_sync_for_woocommerce_target_stores',true);$target_groups=(array)get_post_meta($post->ID,'_kitgenix_multistore_sync_for_woocommerce_target_groups',true);$store_overrides=(array)get_post_meta($post->ID,'_kitgenix_multistore_sync_for_woocommerce_store_overrides',true);$overrides=(array)get_post_meta($post->ID,'_kitgenix_multistore_sync_for_woocommerce_override_fields',true);echo '<div id="kitgenix_multistore_sync_for_woocommerce_product_data" class="panel woocommerce_options_panel hidden">';wp_nonce_field('kitgenix_multistore_sync_for_woocommerce_product_panel','kitgenix_multistore_sync_for_woocommerce_product_nonce');echo '<div class="options_group"><p class="form-field"><label>'.esc_html__('Network ID','kitgenix-multistore').'</label><code>'.esc_html($network?:__('Assigned on first sync','kitgenix-multistore')).'</code></p>';
        woocommerce_wp_checkbox(array('id'=>'_kitgenix_multistore_sync_for_woocommerce_sync_enabled','label'=>__('Network sync','kitgenix-multistore'),'description'=>__('Synchronise this product with selected connected stores.','kitgenix-multistore'),'value'=>$enabled));
        if($this->settings->is_control()){echo '<p class="form-field"><label>'.esc_html__('Target stores','kitgenix-multistore').'</label><span class="kitgenix-multistore-sync-for-woocommerce-checklist">';foreach($this->stores->active()as$s){if('connected'!==$s['role'])continue;$ov=(array)($store_overrides[$s['uuid']]??array());echo '<label><input type="checkbox" name="_kitgenix_multistore_sync_for_woocommerce_target_stores[]" value="'.esc_attr($s['uuid']).'" '.checked(in_array($s['uuid'],$targets,true),true,false).'> '.esc_html($s['name']).'</label><span class="kitgenix-multistore-sync-for-woocommerce-store-price"><input type="text" name="_kitgenix_multistore_sync_for_woocommerce_store_regular['.esc_attr($s['uuid']).']" value="'.esc_attr((string)($ov['regular_price']??'')).'" placeholder="Regular price override"><input type="text" name="_kitgenix_multistore_sync_for_woocommerce_store_sale['.esc_attr($s['uuid']).']" value="'.esc_attr((string)($ov['sale_price']??'')).'" placeholder="Sale price override"></span>'; }echo '<small>'.esc_html__('Leave all stores and groups unchecked to sync to every connected store.','kitgenix-multistore').'</small></span></p>'; $groups=$this->settings->groups();if($groups){echo '<p class="form-field"><label>'.esc_html__('Target groups','kitgenix-multistore').'</label><span class="kitgenix-multistore-sync-for-woocommerce-checklist">';foreach($groups as$gid=>$group){echo '<label><input type="checkbox" name="_kitgenix_multistore_sync_for_woocommerce_target_groups[]" value="'.esc_attr($gid).'" '.checked(in_array($gid,$target_groups,true),true,false).'> '.esc_html($group['name']).'</label>';}echo '</span></p>';}}
        else{echo '<p class="form-field"><label>'.esc_html__('Store overrides','kitgenix-multistore').'</label><span class="kitgenix-multistore-sync-for-woocommerce-checklist">';foreach(\Kitgenix\MultiStore\Support\Settings::policy_fields() as$k=>$label){echo '<label><input type="checkbox" name="_kitgenix_multistore_sync_for_woocommerce_override_fields[]" value="'.esc_attr($k).'" '.checked(in_array($k,$overrides,true),true,false).'> '.esc_html($label).'</label>';}echo '<small>'.esc_html__('Checked fields remain locally managed and are not overwritten by incoming product updates.','kitgenix-multistore').'</small></span></p>';}
        echo '</div></div>';}
    public function save(int$post_id):void{if(empty($_POST['kitgenix_multistore_sync_for_woocommerce_product_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['kitgenix_multistore_sync_for_woocommerce_product_nonce'])),'kitgenix_multistore_sync_for_woocommerce_product_panel'))return;update_post_meta($post_id,'_kitgenix_multistore_sync_for_woocommerce_sync_enabled',isset($_POST['_kitgenix_multistore_sync_for_woocommerce_sync_enabled'])?'yes':'no');$targets=array_values(array_filter(array_map('sanitize_text_field',(array)($_POST['_kitgenix_multistore_sync_for_woocommerce_target_stores']??array()))));$store_prices=array();foreach((array)($_POST['_kitgenix_multistore_sync_for_woocommerce_store_regular']??array())as$uuid=>$price){$uuid=sanitize_text_field($uuid);$regular=wc_format_decimal(wp_unslash($price));$sale=wc_format_decimal(wp_unslash((string)(($_POST['_kitgenix_multistore_sync_for_woocommerce_store_sale'][$uuid]??''))));if(''!==$regular||''!==$sale)$store_prices[$uuid]=array('regular_price'=>$regular,'sale_price'=>$sale);}update_post_meta($post_id,'_kitgenix_multistore_sync_for_woocommerce_store_overrides',$store_prices);update_post_meta($post_id,'_kitgenix_multistore_sync_for_woocommerce_target_stores',$targets);$groups=array_values(array_filter(array_map('sanitize_key',(array)($_POST['_kitgenix_multistore_sync_for_woocommerce_target_groups']??array()))));update_post_meta($post_id,'_kitgenix_multistore_sync_for_woocommerce_target_groups',$groups);$allowed=array_keys(\Kitgenix\MultiStore\Support\Settings::policy_fields());$overrides=array_values(array_intersect($allowed,array_map('sanitize_key',(array)($_POST['_kitgenix_multistore_sync_for_woocommerce_override_fields']??array()))));update_post_meta($post_id,'_kitgenix_multistore_sync_for_woocommerce_override_fields',$overrides);}
}
